// The lru.min table shape in plain JavaScript: parallel slot arrays built as
// new Array(max).fill(undefined), holes read as undefined, indexed writes.
// JSDoc pins the public surface to unknown/number so the record's members are
// not implicit-any; the slot arrays themselves stay any[] (the item under test).
/**
 * @param {number} max
 * @returns {{ put(i: number, key: unknown, value: unknown): void, key(i: number): unknown, value(i: number): unknown, size(): number, capacity(): number }}
 */
function createSlots(max) {
  const keyList = new Array(max).fill(undefined);
  const valList = new Array(max).fill(undefined);
  const next = new Array(max).fill(0);
  let size = 0;
  return {
    put(i, key, value) {
      keyList[i] = key;
      valList[i] = value;
      next[i] = i + 1;
      size++;
    },
    key(i) {
      return keyList[i];
    },
    value(i) {
      return valList[i];
    },
    size() {
      return size;
    },
    capacity() {
      return keyList.length;
    },
  };
}

module.exports = { createSlots };
